/**
 * @method
 * @name btn_fnSubmit_onclick
 * @description btn_fnSubmit 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSubmit_onclick = async function(e){
    try {
        await scwin.fnSubmit()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf45200.btn_fnSubmit_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSubmit
 * @description fn Submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSubmit",
        method: "post",
        action: "/account/userInfo.do",
        ref: "dma_fnSubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSubmit
 * @description fn Submit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSubmit = async function () {
    const fm = (document.SendForm || { elements: [] });
    if ($c.util.getComponent("ipt_perInfo1").checked === false) {
        await $c.win.alert("개인정보 처리방침에 동의해주세요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if ($c.util.getComponent("ipt_perInfo2").checked === false) {
        await $c.win.alert("개인정보 수집 및 이용에 동의해주세요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if (!await scwin.ReqDataCheckValues(fm)) {
        return;
    }
    if (await $c.win.confirm("변경하시겠습니까?")) {
        $c.util.getComponent('dma_fnSubmitReq').set('method', "modifyUserInfo");
        fm.action = "/account/userInfo.do";
        fm.target = "_self";
        await scwin.tx_fnSubmit();
    }
};

/**
 * @method
 * @name fnReset
 * @description fn Reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnReset = function () {
    (document.SendForm || { elements: [] }).reset();
};

/**
 * @method
 * @name ReqDataCheckValues
 * @description Req Data Check Values 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ReqDataCheckValues = async function (fm) {
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctNm').getValue()) === 0) {
        await $c.win.alert("발행기관의 신청인이름을 입력해주십시오.");
        $c.util.getComponent("ipt_apctNm").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctTelNo1').getValue()) === 0) {
        await $c.win.alert("발행기관의 신청인전화번호를 입력해주십시오.");
        $c.util.getComponent("ipt_apctTelNo1").focus();
        return false;
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_apctTelNo2').getValue()) === 0) {
            await $c.win.alert("발행기관의 신청인전화번호를 입력해주십시오.");
            $c.util.getComponent("ipt_apctTelNo2").focus();
            return false;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_apctTelNo3').getValue()) === 0) {
                await $c.win.alert("발행기관의 신청인전화번호를 입력해주십시오.");
                $c.util.getComponent("ipt_apctTelNo3").focus();
                return false;
            }
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_apctFaxNo1').getValue()) === 0) {
        await $c.win.alert("발행기관의 신청인팩스번호를 입력해주십시오.");
        $c.util.getComponent("ipt_apctFaxNo1").focus();
        return false;
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_apctFaxNo2').getValue()) === 0) {
            await $c.win.alert("발행기관의 신청인팩스번호를 입력해주십시오.");
            $c.util.getComponent("ipt_apctFaxNo2").focus();
            return false;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_apctFaxNo3').getValue()) === 0) {
                await $c.win.alert("발행기관의 신청인팩스번호를 입력해주십시오.");
                $c.util.getComponent("ipt_apctFaxNo3").focus();
                return false;
            }
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo1').getValue()) === 0) {
        await $c.win.alert("발행기관의 신청인 휴대폰번호를 입력해주십시오.");
        $c.util.getComponent("ipt_encrypCellphoneNo1").focus();
        return false;
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo2').getValue()) === 0) {
            await $c.win.alert("발행기관의 신청인 휴대폰번호를 입력해주십시오.");
            $c.util.getComponent("ipt_encrypCellphoneNo2").focus();
            return false;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo3').getValue()) === 0) {
                await $c.win.alert("발행기관의 신청인 휴대폰번호를 입력해주십시오.");
                $c.util.getComponent("ipt_encrypCellphoneNo3").focus();
                return false;
            }
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypApctEmail1').getValue()) === 0) {
        await $c.win.alert("발행기관의 신청인 이메일을 입력해주십시오.");
        $c.util.getComponent("ipt_encrypApctEmail1").focus();
        return false;
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_encrypApctEmail2').getValue()) === 0) {
            await $c.win.alert("발행기관의 신청인 이메일을 입력해주십시오.");
            $c.util.getComponent("ipt_encrypApctEmail2").focus();
            return false;
        } else {
            const email = $c.util.getComponent('ipt_encrypApctEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypApctEmail2').getValue();
            if (!$c.str.isEmail(email)) {
                await $c.win.alert("발행기관의 신청인 이메일이 올바르지 않습니다.");
                $c.util.getComponent("ipt_encrypApctEmail2").focus();
                return false;
            }
        }
    }
    return true;
};
